/// `__PROJECT_NAME__.update` (COMMAND): replace a note's body.
pub struct UpdateHandler {
    plan: ExecutionPlan,
    store: Arc<NotesStore>,
}

impl UpdateHandler {
    pub fn new(store: Arc<NotesStore>) -> Self {
        Self {
            plan: ExecutionPlan::new(
                OperationId::from_static(OP_UPDATE),
                ExecutionProfileKind::Command,
            )
            .with_capability(OP_UPDATE),
            store,
        }
    }
}

impl OperationHandler for UpdateHandler {
    fn plan(&self) -> &ExecutionPlan {
        &self.plan
    }

    fn handle(
        &self,
        ctx: Arc<ExecutionContext>,
        input: serde_json::Value,
        unit: &mut dyn ExecutionUnit,
    ) -> BoxFuture<'static, Result<serde_json::Value, AppError>> {
        let outcome = (|| -> Result<serde_json::Value, AppError> {
            let tenant = require_tenant(&ctx)?;
            let id = require_id(&input)?;
            let body = text_field(&input, "body");
            let updated = self.store.update(tenant, id, &body)?;
            unit.record_mutation(MutationRecord {
                resource_type: "note".into(),
                resource_id: Some(id),
                resource_version: 1,
                before: None,
                after: updated.clone(),
                stream: None,
            });
            unit.queue_outbox(OutboxMessage {
                event: EVENT_UPDATED.into(),
                topic: "__PROJECT_NAME__".into(),
                payload: json!({ "id": id.to_string() }),
            });
            Ok(updated)
        })();
        Box::pin(async move { outcome })
    }
}

/// `__PROJECT_NAME__.delete` (COMMAND): remove a note.
pub struct DeleteHandler {
    plan: ExecutionPlan,
    store: Arc<NotesStore>,
}

impl DeleteHandler {
    pub fn new(store: Arc<NotesStore>) -> Self {
        Self {
            plan: ExecutionPlan::new(
                OperationId::from_static(OP_DELETE),
                ExecutionProfileKind::Command,
            )
            .with_capability(OP_DELETE),
            store,
        }
    }
}

impl OperationHandler for DeleteHandler {
    fn plan(&self) -> &ExecutionPlan {
        &self.plan
    }

    fn handle(
        &self,
        ctx: Arc<ExecutionContext>,
        input: serde_json::Value,
        unit: &mut dyn ExecutionUnit,
    ) -> BoxFuture<'static, Result<serde_json::Value, AppError>> {
        let outcome = (|| -> Result<serde_json::Value, AppError> {
            let tenant = require_tenant(&ctx)?;
            let id = require_id(&input)?;
            let removed = self.store.delete(tenant, id)?;
            unit.record_mutation(MutationRecord {
                resource_type: "note".into(),
                resource_id: Some(removed),
                resource_version: 1,
                // A delete transitions the row to nothing: `before` is the last
                // known shape, `after` is JSON null rather than an absent key.
                before: Some(json!({ "id": removed.to_string() })),
                after: json!(null),
                stream: None,
            });
            unit.queue_outbox(OutboxMessage {
                event: EVENT_DELETED.into(),
                topic: "__PROJECT_NAME__".into(),
                payload: json!({ "id": removed.to_string() }),
            });
            Ok(json!({ "id": removed.to_string(), "deleted": true }))
        })();
        Box::pin(async move { outcome })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use kelson_context::{PrincipalContext, ScopeSnapshot, TenantContext};
    use kelson_foundation::{
        codes, AuthorizationRevision, FeatureRevision, ModuleRevision, PrincipalId,
    };
    use kelson_execution::{Engine, InMemoryBackend, InMemoryIdempotency};
    use kelson_policy::{AccessSnapshot, PolicyAuthz, PolicyEngine};
    use time::OffsetDateTime;

    fn fixture(capabilities: &[&str]) -> (Arc<Engine>, Arc<NotesStore>, PrincipalId, TenantId) {
        let principal = PrincipalId::new();
        let tenant = TenantId::new();
        let policies = Arc::new(PolicyEngine::new());
        policies.install_snapshot(AccessSnapshot {
            principal_id: principal,
            tenant_id: tenant,
            membership_active: true,
            capabilities: capabilities.iter().map(|c| c.to_string()).collect(),
            scope_paths: ["/".to_string()].into_iter().collect(),
            authorization_revision: policies.revision(),
            feature_revision: FeatureRevision(1),
            module_revision: ModuleRevision(1),
            computed_at: OffsetDateTime::now_utc(),
        });
        let engine = Arc::new(Engine::new(
            Arc::new(PolicyAuthz { engine: policies }),
            Arc::new(InMemoryBackend::new()),
            Arc::new(InMemoryIdempotency::new()),
        ));
        (
            engine,
            Arc::new(NotesStore::in_memory()),
            principal,
            tenant,
        )
    }

    fn ctx(principal: PrincipalId, tenant: TenantId) -> Arc<ExecutionContext> {
        ExecutionContext::builder(ExecutionProfileKind::Command, OffsetDateTime::now_utc())
            .principal(PrincipalContext {
                id: principal,
                display: Some("starter-test".into()),
            })
            .tenant(TenantContext {
                id: tenant,
                slug: "starter".into(),
                plan: "standard".into(),
            })
            .scope(ScopeSnapshot {
                nodes: vec![],
                revision: AuthorizationRevision(1),
                computed_at: OffsetDateTime::now_utc(),
            })
            .build()
            .unwrap()
    }

    #[tokio::test]
    async fn create_then_list_roundtrips() {
        let (engine, store, principal, tenant) = fixture(ALL_OPS);
        let context = ctx(principal, tenant);
        engine
            .execute(
                context.clone(),
                &CreateHandler::new(store.clone()),
                json!({ "body": "first note" }),
                None,
            )
            .await
            .expect("create succeeds");
        let outcome = engine
            .execute(context, &ListHandler::new(store.clone()), json!({}), None)
            .await
            .expect("list succeeds");
        let notes = outcome.result["notes"].as_array().unwrap();
        assert_eq!(notes.len(), 1);
        assert_eq!(notes[0]["body"], "first note");
    }

    /// Full CRUD in one pass: create, read it back, update it, read the new
    /// body, delete it, then confirm `list` is empty again. This is the
    /// starter's contract — every generated project must satisfy it.
    #[tokio::test]
    async fn full_crud_roundtrips() {
        let (engine, store, principal, tenant) = fixture(ALL_OPS);
        let context = ctx(principal, tenant);

        let created = engine
            .execute(
                context.clone(),
                &CreateHandler::new(store.clone()),
                json!({ "body": "draft" }),
                None,
            )
            .await
            .expect("create succeeds");
        let id = created.result["id"].as_str().unwrap().to_string();

        let read = engine
            .execute(
                context.clone(),
                &ReadHandler::new(store.clone()),
                json!({ "id": id }),
                None,
            )
            .await
            .expect("read succeeds");
        assert_eq!(read.result["body"], "draft");

        let updated = engine
            .execute(
                context.clone(),
                &UpdateHandler::new(store.clone()),
                json!({ "id": id, "body": "final" }),
                None,
            )
            .await
            .expect("update succeeds");
        assert_eq!(updated.result["body"], "final");

        let reread = engine
            .execute(
                context.clone(),
                &ReadHandler::new(store.clone()),
                json!({ "id": id }),
                None,
            )
            .await
            .expect("second read succeeds");
        assert_eq!(reread.result["body"], "final", "update persisted");

        let deleted = engine
            .execute(
                context.clone(),
                &DeleteHandler::new(store.clone()),
                json!({ "id": id }),
                None,
            )
            .await
            .expect("delete succeeds");
        assert_eq!(deleted.result["deleted"], true);

        let after = engine
            .execute(
                context.clone(),
                &ListHandler::new(store.clone()),
                json!({}),
                None,
            )
            .await
            .expect("list succeeds");
        assert_eq!(after.result["notes"].as_array().unwrap().len(), 0);

        // A deleted note must be GONE, not merely hidden from `list`: reading
        // it back under the same tenant is a 404, not an empty payload.
        let error = engine
            .execute(
                context,
                &ReadHandler::new(store.clone()),
                json!({ "id": id }),
                None,
            )
            .await
            .unwrap_err();
        assert_eq!(error.code, codes::NOT_FOUND);
    }

    #[tokio::test]
    async fn empty_body_is_rejected() {
        let (engine, store, principal, tenant) = fixture(&[OP_CREATE]);
        let context = ctx(principal, tenant);
        let error = engine
            .execute(
                context,
                &CreateHandler::new(store.clone()),
                json!({ "body": "   " }),
                None,
            )
            .await
            .unwrap_err();
        assert_eq!(error.code, codes::VALIDATION);
    }

    #[test]
    fn manifest_compiles_into_the_platform_graph() {
        let manifest = kelson_registry::ModuleManifest::from_toml(include_str!("../module.toml"))
            .expect("manifest parses");
        let graph = kelson_registry::PlatformGraph::compile(vec![manifest]).expect("graph compiles");
        assert_eq!(graph.operations.len(), ALL_OPS.len());
        assert_eq!(graph.modules[0].routes.len(), ALL_OPS.len());
        let url = graph
            .resolve_url("__PROJECT_NAME__", "notes.list", &std::collections::BTreeMap::new())
            .expect("named route resolves");
        assert_eq!(url, "/api/v1/__PROJECT_NAME__/notes");
    }

    /// Test provider registering the in-memory ModelStore carrier.
    struct TestModelStoreProvider;

    impl Provider for TestModelStoreProvider {
        fn name(&self) -> &str {
            "test.model-store"
        }
        fn phase(&self) -> Phase {
            Phase::Platform
        }
        fn init(&self, r: &mut ServiceRegistry) -> Result<(), BootError> {
            r.insert(
                "model.store",
                Arc::new(ModelStoreRef(Arc::new(
                    kelson_models::InMemoryModelStore::new(),
                ))),
            )?;
            Ok(())
        }
    }

    #[tokio::test]
    async fn provider_boots_with_the_model_store_port() {
        let mut host = kelson_lifecycle::ApplicationHost::new();
        host.add_provider(Box::new(TestModelStoreProvider));
        host.add_provider(Box::new(ModuleProvider));
        host.boot().await.expect("module boots");
        let bundle = host
            .registry()
            .get::<Vec<Arc<dyn OperationHandler>>>()
            .expect("handlers registered");
        // One handler per published capability.
        assert_eq!(bundle.len(), ALL_OPS.len());
    }
}